using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;

sealed class NativeProtection:IDisposable {
 const long KillRva=0x28faad0,GameSlot=0x5c68c50,Magic=0x334b435452504f54;
 static readonly byte[] Prologue={0x48,0x89,0x5c,0x24,0x08,0x4c,0x89,0x4c,0x24,0x20};
 readonly NativeBridge bridge;readonly string recovery;IntPtr handle;long page,patch;bool installed,disposed;uint[] ids=new uint[0];public uint Blocked {get{return page==0?0:BitConverter.ToUInt32(Read(page+0x410,4),0);}}
 [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint access,bool inherit,int pid);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr h);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool ReadProcessMemory(IntPtr h,IntPtr a,byte[] b,UIntPtr n,out UIntPtr done);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool WriteProcessMemory(IntPtr h,IntPtr a,byte[] b,UIntPtr n,out UIntPtr done);
 [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr VirtualAllocEx(IntPtr h,IntPtr a,UIntPtr n,uint allocation,uint protection);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool VirtualProtectEx(IntPtr h,IntPtr a,UIntPtr n,uint protection,out uint old);
 [DllImport("kernel32.dll")]static extern bool FlushInstructionCache(IntPtr h,IntPtr a,UIntPtr n);
 [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr CreateRemoteThread(IntPtr h,IntPtr attr,UIntPtr stack,IntPtr code,IntPtr arg,uint flags,IntPtr tid);
 [DllImport("kernel32.dll")]static extern uint WaitForSingleObject(IntPtr h,uint milliseconds);
 public NativeProtection(NativeBridge b){bridge=b;recovery=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CK3PersonalTrainer","native-protection.json");handle=OpenProcess(0x43a,false,b.Pid);if(handle==IntPtr.Zero)throw new InvalidOperationException(Lang.T("Нет доступа для нативной защиты."));try{Recover();}catch{CloseHandle(handle);handle=IntPtr.Zero;throw;}}
 byte[] Read(long a,int n){var bytes=new byte[n];UIntPtr done;if(!ReadProcessMemory(handle,(IntPtr)a,bytes,(UIntPtr)n,out done) || done.ToUInt64()!=(ulong)n)throw new InvalidOperationException(Lang.T("Не удалось прочитать состояние нативной защиты."));return bytes;}
 void Write(long a,byte[] bytes){UIntPtr done;if(!WriteProcessMemory(handle,(IntPtr)a,bytes,(UIntPtr)bytes.Length,out done) || done.ToUInt64()!=(ulong)bytes.Length)throw new InvalidOperationException(Lang.T("Не удалось записать состояние нативной защиты."));}
 long Q(long a){return BitConverter.ToInt64(Read(a,8),0);}
 long Atomic(long target,long expected,long next){Write(page+0x800,ProtectionCode.CompareExchange(target,expected,next,page+0x900));FlushInstructionCache(handle,(IntPtr)(page+0x800),(UIntPtr)128);var t=CreateRemoteThread(handle,IntPtr.Zero,UIntPtr.Zero,(IntPtr)(page+0x800),IntPtr.Zero,0,IntPtr.Zero);if(t==IntPtr.Zero)throw new InvalidOperationException(Lang.T("Не удалось выполнить атомарное обновление защиты."));try{if(WaitForSingleObject(t,3000)!=0)throw new InvalidOperationException(Lang.T("Атомарное обновление защиты не ответило. Повтор отменён."));return Q(page+0x900);}finally{CloseHandle(t);}}
 void Recover(){if(!File.Exists(recovery))return;try{var j=new JavaScriptSerializer().Deserialize<Dictionary<string,long>>(File.ReadAllText(recovery));if(j["pid"]!=bridge.Pid || j["start"]!=Process.GetProcessById(bridge.Pid).StartTime.ToUniversalTime().Ticks || j["base"]!=bridge.Base)return;long saved=j["page"];if(Q(saved+0x418)!=Magic)throw new InvalidOperationException(Lang.T("Журнал нативного обработчика не совпадает с памятью."));long current=Q(bridge.Base+KillRva);if(current!=j["patch"]){if(current==BitConverter.ToInt64(Prologue,0)){File.Delete(recovery);return;}throw new InvalidOperationException(Lang.T("Обработчик занят другим кодом; автоматический откат отменён."));}page=saved;patch=j["patch"];installed=true;Uninstall();page=0;}catch(Exception e){throw new InvalidOperationException(Lang.T("Восстановление прежней нативной защиты: ")+e.Message);}}
 void Install(){if(installed)return;long target=bridge.Base+KillRva;if(!Read(target,10).SequenceEqual(Prologue))throw new InvalidOperationException(Lang.T("Обработчик смерти изменён другим инструментом. Защита не установлена."));
  long aligned=target&~0xffffL;for(long distance=0x10000;distance<0x70000000L && page==0;distance+=0x10000){foreach(long a in new[]{aligned+distance,aligned-distance}){if(a<0x10000)continue;page=VirtualAllocEx(handle,(IntPtr)a,(UIntPtr)0x2000,0x3000,0x40).ToInt64();if(page!=0)break;}}
  if(page==0)throw new InvalidOperationException(Lang.T("Не найден свободный блок рядом с обработчиком смерти."));Write(page,ProtectionCode.Guard(page+0x400,bridge.Base+GameSlot,target+10));Write(page+0x400,BitConverter.GetBytes(page+0x1000));Write(page+0x408,BitConverter.GetBytes(bridge.GameState));Write(page+0x418,BitConverter.GetBytes(Magic));Write(page+0x1000,new byte[8]);FlushInstructionCache(handle,(IntPtr)page,(UIntPtr)128);
  var jump=new byte[]{0xe9,0,0,0,0,0x90,0x90,0x90};Array.Copy(BitConverter.GetBytes(checked((int)(page-target-5))),0,jump,1,4);patch=BitConverter.ToInt64(jump,0);long original=BitConverter.ToInt64(Prologue,0);uint old;
  Directory.CreateDirectory(Path.GetDirectoryName(recovery));AtomicStorage.Write(recovery,new JavaScriptSerializer().Serialize(new Dictionary<string,long>{{"pid",bridge.Pid},{"start",Process.GetProcessById(bridge.Pid).StartTime.ToUniversalTime().Ticks},{"base",bridge.Base},{"page",page},{"patch",patch}}));
  if(!VirtualProtectEx(handle,(IntPtr)target,(UIntPtr)8,0x40,out old))throw new InvalidOperationException(Lang.T("Не удалось открыть обработчик для атомарного обновления."));try{if(Atomic(target,original,patch)!=original)throw new InvalidOperationException(Lang.T("Обработчик поменялся во время установки. Запись отменена."));installed=true;FlushInstructionCache(handle,(IntPtr)target,(UIntPtr)8);}finally{uint ignored;VirtualProtectEx(handle,(IntPtr)target,(UIntPtr)8,old,out ignored);}

 }
 public void Set(IEnumerable<uint> requested){if(disposed)throw new ObjectDisposedException("NativeProtection");bridge.Refresh();uint[] next=requested.Distinct().OrderBy(x=>x).ToArray();if(next.Length>1000)throw new InvalidOperationException(Lang.T("Защита поддерживает до 1000 явно выбранных персонажей."));foreach(uint id in next)if(!bridge.LivingCharacter(id))throw new InvalidOperationException(Lang.T("Защита доступна только живому персонажу: ")+id);if(ids.SequenceEqual(next))return;if(next.Length==0){if(installed){long prior=Q(page+0x400);if(Atomic(page+0x400,prior,page+0x1000)!=prior)throw new InvalidOperationException(Lang.T("Список защиты изменён извне."));}ids=next;return;}Install();if(Q(page+0x408)!=bridge.GameState)throw new InvalidOperationException(Lang.T("Нативная защита относится к другой кампании. Переподключись."));long table=VirtualAllocEx(handle,IntPtr.Zero,(UIntPtr)4096,0x3000,0x04).ToInt64();if(table==0)throw new InvalidOperationException(Lang.T("Не удалось создать список защищаемых целей."));var bytes=new byte[8+next.Length*4];Array.Copy(BitConverter.GetBytes(next.Length),bytes,4);for(int i=0;i<next.Length;i++)Array.Copy(BitConverter.GetBytes(next[i]),0,bytes,8+i*4,4);Write(table,bytes);long previous=Q(page+0x400);if(Atomic(page+0x400,previous,table)!=previous)throw new InvalidOperationException(Lang.T("Список защиты обновил другой инструмент."));ids=next;}
 public uint[] Targets {get{return ids.ToArray();}}
 public long AttachedGameState {get{return installed?Q(page+0x408):bridge.GameState;}}
 void Uninstall(){if(!installed || !bridge.Alive)return;long target=bridge.Base+KillRva;long prior=Q(page+0x400);if(Atomic(page+0x400,prior,page+0x1000)!=prior)throw new InvalidOperationException(Lang.T("Список защиты изменён извне."));uint old;if(!VirtualProtectEx(handle,(IntPtr)target,(UIntPtr)8,0x40,out old))throw new InvalidOperationException(Lang.T("Не удалось восстановить обработчик смерти."));try{if(Atomic(target,patch,BitConverter.ToInt64(Prologue,0))!=patch)throw new InvalidOperationException(Lang.T("Обработчик смерти изменён извне. Чужой код не перезаписан."));FlushInstructionCache(handle,(IntPtr)target,(UIntPtr)8);installed=false;File.Delete(recovery);}finally{uint ignored;VirtualProtectEx(handle,(IntPtr)target,(UIntPtr)8,old,out ignored);}}
 public void Dispose(){if(disposed)return;try{if(bridge.Alive)Uninstall();}finally{disposed=true;CloseHandle(handle);handle=IntPtr.Zero;}}

}
